#!/usr/bin/env python3
"""Generate the C lifter's pinned state-hook table from the JSON source."""

from __future__ import annotations

import argparse
import sys
from pathlib import Path

from state_hooks import StateHookError, load_hooks


def render(hooks) -> str:
    lines = [
        "/* AUTO-GENERATED by tools/lift/gen_state_hooks.py - do not edit. */",
        "#ifndef WC3_STATE_HOOKS_GEN_H",
        "#define WC3_STATE_HOOKS_GEN_H",
        "",
        "typedef struct Wc3StateHook {",
        "    uint32_t store_va;",
        "    unsigned kind;",
        "    const char *value;",
        "    const char *guard;",
        "    const char *name;",
        "} Wc3StateHook;",
        "",
        "static const Wc3StateHook wc3_state_hooks[] = {",
    ]
    for hook in hooks:
        value = hook.value
        guard = hook.guard if hook.guard is not None else "0"
        lines.append(
            f'    {{ {hook.store_va:#010x}u, {hook.kind}u, "{value}", '
            f'"{guard}", "{hook.name}" }},')
    lines += [
        "};",
        "",
        "#define WC3_STATE_HOOK_COUNT \\",
        "    (sizeof(wc3_state_hooks) / sizeof(wc3_state_hooks[0]))",
        "",
        "#endif /* WC3_STATE_HOOKS_GEN_H */",
        "",
    ]
    return "\n".join(lines)


def main(argv: list[str] | None = None) -> int:
    parser = argparse.ArgumentParser()
    parser.add_argument("--table", type=Path, default=None)
    parser.add_argument("--out", type=Path, required=True)
    parser.add_argument("--check", action="store_true")
    args = parser.parse_args(argv)

    try:
        hooks = load_hooks(args.table)
    except StateHookError as exc:
        print(f"state_hooks: {exc}", file=sys.stderr)
        return 1

    text = render(hooks)
    if args.check:
        try:
            current = args.out.read_text(encoding="utf-8")
        except FileNotFoundError:
            print(f"state_hooks: missing generated header {args.out}",
                  file=sys.stderr)
            return 1
        if current != text:
            print(f"state_hooks: stale generated header {args.out}",
                  file=sys.stderr)
            return 1
        return 0

    args.out.parent.mkdir(parents=True, exist_ok=True)
    args.out.write_text(text, encoding="utf-8", newline="\n")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
